/* Gooners AI service worker (generated by build/serviceWorker.ts; do not edit dist/sw.js). */
const VERSION = '__VERSION__';
/** Small files precached at install: the app opens offline after the first visit. */
const SHELL = __SHELL__;
/** Large runtimes (.wasm), cached the first time they are requested or on demand ("warm"). */
const LAZY = __LAZY__;

// Every cache this worker owns starts with this prefix; other apps on the origin are left alone.
const PREFIX = 'gooners-ai-';
const SHELL_CACHE = `${PREFIX}shell-${VERSION}`;
const RUNTIME_CACHE = `${PREFIX}runtime`;
const scoped = (path) => new URL(path, self.registration.scope).href;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) => cache.addAll(SHELL.map((p) => new Request(scoped(p), { cache: 'reload' })))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) {
        if (key.startsWith(`${PREFIX}shell-`) && key !== SHELL_CACHE) await caches.delete(key);
      }
      const keep = new Set(LAZY.map(scoped));
      const runtime = await caches.open(RUNTIME_CACHE);
      for (const request of await runtime.keys()) {
        if (!keep.has(request.url)) await runtime.delete(request);
      }
      await self.clients.claim();
    })(),
  );
});

async function fromCache(request) {
  const shell = await caches.open(SHELL_CACHE);
  return (await shell.match(request)) || (await (await caches.open(RUNTIME_CACHE)).match(request));
}

async function cacheFirst(request) {
  const hit = await fromCache(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok && response.type === 'basic' && LAZY.some((p) => scoped(p) === request.url)) {
    const copy = response.clone();
    caches.open(RUNTIME_CACHE).then((cache) => cache.put(request, copy));
  }
  return response;
}

async function navigation(request) {
  const shell = await caches.open(SHELL_CACHE);
  const hit = (await shell.match(scoped('./'))) || (await shell.match(scoped('index.html')));
  if (hit) return hit;
  return fetch(request);
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET' || request.headers.has('range')) return;
  if (!request.url.startsWith(self.registration.scope)) return;
  if (request.mode === 'navigate') {
    event.respondWith(navigation(request).catch(() => fetch(request)));
    return;
  }
  event.respondWith(cacheFirst(request).catch(() => fetch(request)));
});

self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type === 'skip-waiting') {
    self.skipWaiting();
  } else if (data.type === 'status' || data.type === 'warm') {
    const port = event.ports[0];
    event.waitUntil(
      (async () => {
        const runtime = await caches.open(RUNTIME_CACHE);
        const missing = [];
        for (const path of LAZY) if (!(await runtime.match(scoped(path)))) missing.push(path);
        if (data.type === 'warm') {
          for (const path of missing.splice(0)) {
            try {
              const response = await fetch(scoped(path), { cache: 'reload' });
              if (response.ok) await runtime.put(scoped(path), response);
              else missing.push(path);
            } catch {
              missing.push(path);
            }
          }
        }
        port?.postMessage({ version: VERSION, shell: SHELL.length, lazy: LAZY.length, missing });
      })(),
    );
  }
});
